#include <bits/stdc++.h>
using namespace std;

const int MAXNODES = 510;

int M, N, MOD;

inline int add_mod(int a, int b) { return (a + b) % MOD; }
inline int subtract_mod(int a, int b) { return a - b < 0 ? a - b + MOD : a - b; }
inline int multiply_mod(int a, int b) { return (long long) a * b % MOD; }

int fact[MAXNODES], inv_fact[MAXNODES], invs[MAXNODES];

void precompute(int limit)
{
    fact[0] = 1; invs[1] = 1; fact[1] = 1; inv_fact[0] = 1; inv_fact[1] = 1;
    for (int i = 2; i <= limit; i++) invs[i] = multiply_mod((MOD - MOD / i), invs[MOD % i]);
    for (int i = 2; i <= limit; i++) { fact[i] = multiply_mod(fact[i - 1], i); inv_fact[i] = multiply_mod(inv_fact[i - 1], invs[i]); }
}

int choose(int n, int r) {
    if (n < r || r < 0) return 0;
    return multiply_mod(multiply_mod(fact[n], inv_fact[r]), inv_fact[n - r]);
}

int arrangements(int n, int r) {
    return choose(n + r - 1, r - 1);
}

int f_array[MAXNODES], g_array[MAXNODES], prefix_sum[MAXNODES];
int f_table[MAXNODES][MAXNODES], g_table[MAXNODES][MAXNODES];

int main()
{
    scanf("%d %d %d", &N, &M, &MOD);
    precompute(500);
    for (int i = 1; i <= N; i++) prefix_sum[i] = add_mod(prefix_sum[i - 1], i);
    f_array[0] = 1; f_array[1] = 2;
    g_array[0] = 0; g_array[1] = 0;
    for (int i = 2; i <= N; i++)
    {
        for (int j = 0; j < i; j++)
        {
            int temp_val = multiply_mod(choose(i - 1, j), multiply_mod(f_array[j], f_array[i - 1 - j]));
            f_array[i] = add_mod(f_array[i], multiply_mod(temp_val, i + 1));
            g_array[i] = add_mod(g_array[i], multiply_mod(temp_val, prefix_sum[j] + prefix_sum[i - 1 - j]));
            int temp2 = multiply_mod(add_mod(multiply_mod(g_array[j], f_array[i - 1 - j]), multiply_mod(g_array[i - 1 - j], f_array[j])), i + 1);
            g_array[i] = add_mod(g_array[i], multiply_mod(temp2, choose(i - 1, j)));
        }
    }
    f_table[0][0] = 1; g_table[0][0] = 0;
    for (int i = 0; i <= M; i++)
        for (int j = 0; j <= M; j++)
        {
            if (f_table[i][j] == 0) continue;
            for (int k = 1; k + j <= M; k++)
            {
                f_table[i + 1][j + k] = add_mod(f_table[i + 1][j + k], multiply_mod(multiply_mod(f_table[i][j], f_array[k]), choose(j + k, k)));
                g_table[i + 1][j + k] = add_mod(g_table[i + 1][j + k], multiply_mod(add_mod(multiply_mod(g_table[i][j], f_array[k]), multiply_mod(f_table[i][j], g_array[k])), choose(j + k, k)));
            }
        }
    int final_ans = 0;
    for (int i = 1; i <= M; i++)
        if (N + 1 - M >= i)
            final_ans = add_mod(final_ans, multiply_mod(g_table[i][M], arrangements(N + 1 - M - i, i + 1)));
    printf("%d\n", final_ans);
    return 0;
}
